221: async function resolveSingleServer({ server, type, tmdbId, season, episode, wasmModule }) {
222:   const instance = await WebAssembly.instantiate(wasmModule);
223:   const { responseKey, keyId, ephemeralPublic, ciphertextBody } = sealRequest(instance, {
224:     server, type, tmdbId, season, episode
225:   });
226: 
227:   const gatewayRes = await fetch(GATEWAY_URL, {
228:     method: 'POST',
